I did  

```c
static const char *  // Check server version from banner
ssh_get_kex_version_string(wmem_array_t *version_array, wmem_allocator_t *scope) {
    if (!version_array) return NULL;

    const uint8_t *raw = (const uint8_t *)wmem_array_get_raw(version_array);
    uint32_t total_len = wmem_array_get_count(version_array);
    if (raw == NULL || total_len < 4)
        return NULL;

    if (!raw || total_len < 4 || total_len > 516)
        return NULL;

    uint32_t len = (raw[0] << 24) | (raw[1] << 16) | (raw[2] << 8) | raw[3];
    // Sanity: check if len matches the actual payload length
    if (len == 0 || (len + 4) != total_len)
        return NULL;

    return wmem_strndup(scope, (const char *)(raw + 4), len);
}
```

